from collections import Counter

class Solution:
    def minimumIndex(self, nums: List[int]) -> int:
        n = len(nums)
        # Find the dominant element (the unique majority of the whole array)
        cnt = Counter(nums)
        d, total = cnt.most_common(1)[0]

        left = 0
        for i in range(n - 1):
            if nums[i] == d:
                left += 1
            right = total - left
            left_len = i + 1
            right_len = n - i - 1
            if left * 2 > left_len and right * 2 > right_len:
                return i
        return -1
