import json
from hypothesis import strategies as st


def _dominant(arr):
    # Literal definition: x is dominant iff freq(x) * 2 > len(arr). Returns None if none.
    m = len(arr)
    for x in set(arr):
        if arr.count(x) * 2 > m:
            return x
    return None


@st.composite
def gen(draw):
    n = draw(st.integers(1, 8))
    nums = draw(
        st.lists(st.integers(1, 3), min_size=n, max_size=n)
        .filter(lambda a: _dominant(a) is not None)
    )
    return json.dumps(nums)


def validate(inp):
    try:
        nums = json.loads(inp)
    except Exception:
        return False
    if not isinstance(nums, list):
        return False
    n = len(nums)
    if not (1 <= n <= 10**5):
        return False
    for v in nums:
        if type(v) is not int or not (1 <= v <= 10**9):
            return False
    # Must have exactly one dominant element (at most one always holds; need at least one).
    return _dominant(nums) is not None


def ref(inp):
    nums = json.loads(inp)
    n = len(nums)
    total_dom = _dominant(nums)
    for i in range(0, n - 1):
        left = nums[: i + 1]
        right = nums[i + 1:]
        dl = _dominant(left)
        dr = _dominant(right)
        if dl is not None and dl == dr and dl == total_dom:
            return json.dumps(i)
    return json.dumps(-1)
