import json
from collections import Counter
from hypothesis import strategies as st


@st.composite
def gen(draw):
    n = draw(st.integers(1, 12))
    d = draw(st.integers(1, 5))
    # Dominant element must occur strictly more than n/2 times.
    k = draw(st.integers(n // 2 + 1, n))
    others = draw(st.lists(st.integers(1, 5), min_size=n - k, max_size=n - k))
    arr = [d] * k + others
    arr = draw(st.permutations(arr))
    return json.dumps(list(arr))


def validate(inp):
    try:
        arr = json.loads(inp)
    except Exception:
        return False
    if not isinstance(arr, list):
        return False
    n = len(arr)
    if not (1 <= n <= 10**5):
        return False
    for x in arr:
        if not isinstance(x, int) or isinstance(x, bool):
            return False
        if not (1 <= x <= 10**9):
            return False
    cnt = Counter(arr)
    dominants = [x for x, c in cnt.items() if c * 2 > n]
    return len(dominants) == 1


def _dom(lst):
    m = len(lst)
    for x in set(lst):
        if lst.count(x) * 2 > m:
            return x
    return None


def ref(inp):
    nums = json.loads(inp)
    n = len(nums)
    total = _dom(nums)
    for i in range(0, n - 1):
        left = nums[:i + 1]
        right = nums[i + 1:]
        if _dom(left) == total and _dom(right) == total and total is not None:
            return json.dumps(i)
    return json.dumps(-1)
